"""Generate baseline_b9_pvp.steps (N poke blocks; the steps format has no loops)."""
from pathlib import Path

N = 20
SPOT = "32369,32215,7"
L = [
    "# SCENARIO: baseline_b9_pvp   SEED: 0   CAMERAS: none   BOTCFG: auto",
    "# Phase 3 (lean) baseline B9 - PvP poke outside PZ. NORMAL AI. Generated by gen_b9.py.",
    "# The non-GM harness char (level 8) attacks a different visible bot per block at a Thais street",
    "# crossing, holds 8 s, stops. Spec (bot_combat.cpp onAttacked): bot >= 2x attacker level ->",
    "# 17% fight / 83% ignore, else 50/50 fight/flee. Level 8 attacker => every bot >= level 16 is the",
    "# OUTLEVEL branch. Detection needs the attacker PZ-locked AND targeting the bot (doSelfDefense).",
    "# A fight usually kills the harness char: every block starts with `login optional=1` (SKIP while",
    f"# still online, re-login after death). Run with --var V1=none ... --var V{N}=none.",
    "# Server truth: audit state (watch * -> COMBAT/FLEEING). Metrics: baseline_metrics.py b9.",
    "@srv audit kinds state,cmd,census",
    "@srv audit watch *",
    '@srv audit on expect="enabled=on"',
    '@srv audit mark "B9 start"',
    "@p1 login",
    f"@p1 goto {SPOT} range=3 stuck=15 timeout=120",
    "@p1 self",
]
prev = []
for k in range(1, N + 1):
    v = f"V{k}"
    notl = (" not=" + ",".join("$" + p for p in prev)) if prev else ""
    L += [
        "@p1 login optional=1",
        f"@p1 goto {SPOT} range=4 stuck=15 timeout=90 optional=1",
        f"@p1 wait-see any-bot timeout=60{notl} as={v} optional=1",
        f'@srv audit mark "B9 poke {k} ${v}"',
        f"@p1 attack ${v} optional=1",
        "@p1 hold 8 optional=1",
        "@p1 attack stop optional=1",
        "@p1 hold 4 optional=1",
    ]
    prev.append(v)
L += ['@srv audit mark "B9 end"', "@srv audit watch clear", "@srv audit off", "@p1 logout"]
Path(__file__).with_name("baseline_b9_pvp.steps").write_text("\n".join(L) + "\n", encoding="utf-8")
print(f"wrote {len(L)} lines")
